def gen(rng):
    def fmt(v):
        return str(len(v)) + '\n' + ' '.join(map(str, v))
    tests = [fmt([5]), fmt([1, 2]), fmt([1, 2, 3]), fmt([1, 2, 3, 4]), fmt([-3, 0, 9]),
             fmt([1, 2, 3, 4, 5]), fmt([-10, -5, 0, 5, 10, 15])]
    for n in list(range(1, 31)) + [31, 32, 33, 40, 50]:
        v = sorted(rng.sample(range(-1000, 1000), n))
        tests.append(fmt(v))
    for n in (100000, 99999, 65535, 65536):
        v = sorted(rng.sample(range(-10 ** 9, 10 ** 9 + 1), n))
        tests.append(fmt(v))
    return tests
